package kr.co.cudo.authoring.external.dto;

import io.swagger.v3.oas.annotations.media.Schema;
import kr.co.cudo.authoring.batch.entity.LsDataLbl;
import kr.co.cudo.authoring.batch.entity.LsDataLblAiInfo;

import java.math.BigDecimal;
import java.util.List;

/**
 * Phase 4 — 외부 학습데이터 API 라벨 단위 응답.
 *
 * <p>POINTS_JSON 은 JSON 배열로 직렬화되어 {@code List<List<Double>>} 로 노출.
 * BBOX 의 경우 [[x1,y1],[x2,y2]], POLYGON 은 N개 점.
 *
 * <p>Phase 6 (LS_DATA_LBL_AI_INFO 분리) 이후 자동 라벨 여부/신뢰도/출처는
 * AI 정보 테이블에서 가져온다. AI 정보가 없으면 수동 라벨로 간주
 * ({@code autoGenerated=false}, {@code confidence=null}, {@code lblSrcCd=null}).
 */
@Schema(description = "라벨 단위 응답 (BBOX/POLYGON/SEGMENT/TRACK)")
public record LabelInfo(
        @Schema(description = "라벨 타입 (BBOX/POLYGON/SEGMENT/TRACK)") String type,
        @Schema(description = "라벨명 (예: person, car)") String label,
        @Schema(description = "좌표 배열 (BBOX 는 2점, POLYGON 은 N점)") List<List<Double>> points,
        @Schema(description = "자동 라벨 여부") Boolean autoGenerated,
        @Schema(description = "신뢰도 (0.0~1.0, NULL 가능)") BigDecimal confidence,
        @Schema(description = "트래커 부여 객체 ID (NULL 가능)") String trackId,
        @Schema(description = "라벨 출처 코드 (YOLO/SAM2/INTERPOLATE/VLM 또는 NULL)") String lblSrcCd
) {
    /**
     * LS_DATA_LBL + (옵션) LS_DATA_LBL_AI_INFO 로부터 외부 응답 LabelInfo 를 조립.
     * AI 정보가 없으면 수동 라벨로 간주: autoGenerated=false / confidence=null / lblSrcCd=null.
     *
     * @param lbl       라벨 본체 (좌표/타입/라벨명/trackId)
     * @param aiInfo    선택 — AI 정보 (자동 여부/신뢰도/출처/모델). null 허용.
     * @param points    파싱된 좌표 (NULL 안전 — service 가 빈 배열로 전달)
     */
    public static LabelInfo from(LsDataLbl lbl, LsDataLblAiInfo aiInfo, List<List<Double>> points) {
        boolean autoGenerated = aiInfo != null && LsDataLbl.AUTO_YES.equals(aiInfo.getAutoLblYn());
        BigDecimal confidence = aiInfo != null ? aiInfo.getConfScore() : null;
        String lblSrcCd = aiInfo != null ? aiInfo.getLblSrcCd() : null;
        return new LabelInfo(
                lbl.getLblTypeCd(),
                lbl.getLabel(),
                points,
                autoGenerated,
                confidence,
                lbl.getTrackId(),
                lblSrcCd
        );
    }
}
